// Talent-Reports (ALLY 27, BA5, Stefan 20.10.2026): Report erstellen (Dialog je Art), Vorlagen, erstellte Reports. Daten wie ALLY 8 (talents_berichte_web).
// Aktionen (neu, statt des eigenen Ziels von TALENTS Web): tr_bericht (modus erstellen | vorlage_speichern; Felder wie TALENTS Web: art, vorlage_id, talents,
// kampagne_id, kanal, monat, zeitraum, von, bis, bausteine, titel, mit_agentur, vorlage_name, plan), tr_vorlage_erstellen (vorlage_id, monat), tr_vorlage_loeschen (vorlage_id).
// Erstellte Reports liegen im Speicherort; „PDF herunterladen“ und die Monatswahl ergänzt der Knoten „Downloads und Monatswahl“. Liefert nur die Seitenbeschreibung (JSON).
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const titel = String(F.name || 'Reports');
const kopf = { schluessel: 'talent-reports', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
if (/^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || ''))) kopf.zahnrad = { ziel: { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } };
const R = D.r;
if (D.ok !== true || !R || R.ok !== true) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: String((R && R.fehler) || 'Die Reports konnten nicht geladen werden. Bitte neu laden.') }] } } }];
const L = x => Array.isArray(x) ? x : [];
const id9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? String(v) : '';
const ARTEN = L(R.arten), TL = L(R.talents).filter(t => id9(t.id));
const tName = t => String(t.anzeigename || '') + (t.archiviert ? ' (im Papierkorb)' : '');
const BL = R.berichte && typeof R.berichte === 'object' ? R.berichte : {}, BZ = L(BL.zeilen);
const VL = R.vorlagen && typeof R.vorlagen === 'object' ? R.vorlagen : {}, VZ = L(VL.zeilen).filter(x => id9(x.id));
const MON = L(R.monate);
const filterWerte = Object.assign({}, P.art ? { art: P.art } : {}, P.talent ? { talent: P.talent } : {});
const hier = (extra, anker) => ({ seite: 'talent-reports', parameter: Object.assign({}, filterWerte, extra || {}), anker });
const fertig = BZ.filter(x => x.status === 'fertig').length, fehler = BZ.filter(x => x.status === 'fehler');
const ueberblick = { kennzahlen: [
  { label: 'Reports', wert: String(BL.anzahl ?? BZ.length), neben: '' },
  { label: 'Fertig', wert: String(fertig), neben: 'auf dieser Seite' },
  { label: 'In Arbeit', wert: BL.laeuft === true ? 'ja' : 'nein', neben: '' },
  { label: 'Vorlagen', wert: String(VL.anzahl ?? VZ.length), neben: VZ.filter(v => v.plan && v.plan !== 'aus').length ? VZ.filter(v => v.plan && v.plan !== 'aus').length + ' regelmäßig' : '' }],
  karten: [
    { titel: 'Offen', leer: 'Nichts offen.', eintraege: BL.laeuft === true ? [{ marke: { text: 'läuft', ton: 'info' }, text: 'Ein Report wird gerade erstellt.' }] : [] },
    { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: fehler.slice(0, 3).map(x => ({ marke: { text: 'Fehler', ton: 'warn' }, text: String(x.titel || ''), neben: String(x.status_text || '') }))
      .concat(VZ.filter(v => v.letzter_fehler).slice(0, 3).map(v => ({ marke: { text: 'Vorlage', ton: 'warn' }, text: String(v.name || '') + ': ' + String(v.letzter_fehler) }))) }] };
// Erstellte Reports und Vorlagen: die Datenbank blättert (talents_berichte_liste / talents_vorlagen_liste, je_seite aus der Datenbank, heute 10)
const abschnitte = [{ id: 'berichte', titel: 'Erstellte Reports', zahl: String(BL.anzahl ?? BZ.length), offen_standard: true, inhalt: [
  { typ: 'filter', id: 'berichte', label: 'Reports filtern', felder: [
    { typ: 'auswahl', name: 'art', label: 'Art', wert: String(P.art || ''), optionen: [{ wert: '', text: 'Alle Arten' }].concat(ARTEN.map(a => ({ wert: a.schluessel, text: String(a.name) }))) },
    { typ: 'auswahl', name: 'talent', label: 'Talent', wert: id9(P.talent), optionen: [{ wert: '', text: 'Alle Talents' }].concat(TL.map(t => ({ wert: id9(t.id), text: tName(t) }))) }] },
  { typ: 'tabelle', id: 'berichte', titel: 'Erstellte Reports', spalten: [{ schluessel: 'titel', titel: 'Report' }, { schluessel: 'art', titel: 'Art und Zeitraum' },
    { schluessel: 'erstellt', titel: 'Erstellt' }, { schluessel: 'status', titel: 'Stand' }, { schluessel: 'ort', titel: 'Speicherort' }],
    zeilen: BZ.map(x => ({ zellen: { titel: { text: String(x.titel || ''), fett: true }, art: [x.art_name, x.zeitraum_text].filter(Boolean).join(' · '),
      erstellt: [x.erstellt_text, x.erstellt_von_name, x.quelle_text].filter(Boolean).join(' · '),
      // Layout 4 (Plan 30, Prüfliste 5): „nicht erstellt: <Grund>“ – Marke kurz, Grund am i der Zelle
      status: (m => Object.assign({ marke: { text: m ? m[1] : String(x.status_text || x.status || ''), ton: x.status === 'fehler' ? 'warn' : x.status === 'fertig' ? 'ok' : 'info' } },
        m ? { info: m[2], info_name: 'Grund' } : {}))(x.status === 'fehler' ? /^([^:]{1,40}):\s+(.+)$/.exec(String(x.status_text || '')) : null),
      ort: x.pfad ? { text: String(x.pfad), neben: String(x.ort || '') } : '–' } })),
    sortierung: {}, seite: Math.max(1, Number(BL.seite) || 1), je_seite: Math.max(1, Number(BL.je_seite) || 10), gesamt: Number(BL.anzahl ?? BZ.length) || 0, leer: String(BL.leer_text || 'Noch keine Reports erstellt.') }] }];
// Vorlagen
abschnitte.push({ id: 'vorlagen', titel: 'Vorlagen', zahl: String(VL.anzahl ?? VZ.length), offen_standard: false, inhalt: [{ typ: 'tabelle', id: 'vorlagen', titel: 'Vorlagen',
  spalten: [{ schluessel: 'name', titel: 'Vorlage' }, { schluessel: 'art', titel: 'Art und Talents' }, { schluessel: 'plan', titel: 'Wiederholung' }, { schluessel: 'aktion', titel: 'Aktion' }],
  zeilen: VZ.map(x => ({ zellen: { name: Object.assign({ text: String(x.name || ''), ziel: hier({ vorlage: id9(x.id) }) }, x.letzter_fehler ? { neben: 'Letzter Lauf: ' + String(x.letzter_fehler) } : {}),
    art: { text: [x.art_name, x.talents_text].filter(Boolean).join(' · '), neben: x.bausteine_text ? 'Bausteine: ' + String(x.bausteine_text) : '' },
    plan: [x.plan_text, x.naechster_text, x.letzter_text].filter(Boolean).join(' · ') || '–',
    aktion: { aktion: { text: 'Jetzt erstellen', aktion: 'tr_vorlage_erstellen', werte: { vorlage_id: id9(x.id) }, frage: 'Report aus „' + String(x.name || '') + '“ jetzt erstellen?' } } } })),
  sortierung: {}, seite: Math.max(1, Number(VL.seite) || 1), je_seite: Math.max(1, Number(VL.je_seite) || 10), gesamt: Number(VL.anzahl ?? VZ.length) || 0, leer: String(VL.leer_text || 'Noch keine Vorlagen.') }] });
// Report erstellen (Dialog, vom Server geöffnet, wenn eine Art oder Vorlage gewählt ist)
const FM = R.formular || {}, art = ARTEN.find(a => a.schluessel === FM.art) || null;
const V = FM.vorlage && typeof FM.vorlage === 'object' ? FM.vorlage : null, VA = V && V.auftrag && typeof V.auftrag === 'object' ? V.auftrag : null;
const EF = D.ef && typeof D.ef === 'object' && art && D.ef.art === art.schluessel ? D.ef : null;
const liste = v => (Array.isArray(v) ? v : String(v ?? '').split(',')).map(x => id9(String(x).trim())).filter(Boolean);
const neuInhalt = [{ typ: 'filter', id: 'art', label: 'Art des Reports', felder: [{ typ: 'auswahl', name: 'neu', label: 'Art', wert: art ? art.schluessel : '',
  optionen: [{ wert: '', text: 'Art wählen' }].concat(ARTEN.map(a => ({ wert: a.schluessel, text: String(a.name) }))) }] }];
if (art) {
  const k = art.schluessel, KP = R.kampagnen && typeof R.kampagnen === 'object' ? R.kampagnen : {}, KL = L(KP.kampagnen).filter(x => id9(x.id));
  const tmin = Number(art.talents_min) || 0, tmax = Number(art.talents_max) || 0;
  const vorT = id9(P.talent) && TL.some(t => id9(t.id) === id9(P.talent)) ? id9(P.talent) : '';
  const gT = VA ? liste(VA.talents) : EF ? liste(EF.talents) : vorT ? [vorT] : [];
  const zr = VA && VA.zeitraum && typeof VA.zeitraum === 'object' ? VA.zeitraum : EF ? { zeitraum: EF.zeitraum, von: EF.von, bis: EF.bis } : { zeitraum: art.zeitraum };
  const gBau = VA ? L(VA.bausteine) : EF ? (Array.isArray(EF.bausteine) ? EF.bausteine : String(EF.bausteine || '').split(',')) : ['kennzahlen', 'beitraege'];
  const gAgentur = VA ? VA.mit_agentur !== false : EF ? !['nein', 'false', '0'].includes(String(EF.mit_agentur)) : true;
  const felder = [];
  // Layout 4 (Plan 30, Prüfliste 5): Beschreibung der Art am i des Feldes „Art“ statt als graue Zeile
  if (art.beschreibung) neuInhalt[0].felder[0].info = String(art.beschreibung);
  if (k === 'kampagne' && !KL.length) neuInhalt.push({ typ: 'hinweis', ton: 'info', text: String(KP.hinweis || 'Es gibt noch keine Kampagne für einen Report.') });
  else {
    if (k !== 'kampagne') {
      if (tmax === 1) felder.push({ typ: 'auswahl', name: 'talents', label: 'Talent', pflicht: true, wert: gT[0] || '', breite: 'voll', optionen: [{ wert: '', text: 'Talent wählen' }].concat(TL.map(t => ({ wert: id9(t.id), text: tName(t) }))) });
      else felder.push({ typ: 'mehrfach', name: 'talents', label: 'Talents (' + tmin + ' bis ' + tmax + ')', wert: gT, breite: 'voll', optionen: TL.map(t => ({ wert: id9(t.id), text: tName(t) })) });
    }
    const kampOpt = KL.map(x => ({ wert: id9(x.id), text: [x.name || [x.marke, x.titel].filter(Boolean).join(' – '), x.zeitraum_text, x.status_text].filter(Boolean).join(' · ') }));
    // 2c-5 (Stefan 24.10.2026): Kampagne aus dem Link „Kampagnenreport“ der Kampagne (?kampagne=<id>) vorwählen, wenn sie zur Auswahl gehört
    const gKamp = id9(VA ? VA.kampagne_id : EF ? EF.kampagne_id : KL.some(x => id9(x.id) === id9(P.kampagne)) ? P.kampagne : '');
    if (k === 'kampagne') felder.push({ typ: 'auswahl', name: 'kampagne_id', label: 'Kampagne', pflicht: true, wert: gKamp, breite: 'voll', optionen: [{ wert: '', text: 'Kampagne wählen' }].concat(kampOpt) });
    if (k === 'wunsch' && KL.length) felder.push({ typ: 'auswahl', name: 'kampagne_id', label: 'Kampagne (nur für den Baustein Kampagne)', wert: gKamp, breite: 'voll', optionen: [{ wert: '', text: 'keine' }].concat(kampOpt) });
    if (['monat', 'vergleich', 'wunsch'].includes(k)) felder.push({ typ: 'auswahl', name: 'kanal', label: 'Kanal', wert: String((VA ? VA.kanal : EF ? EF.kanal : '') || ''), optionen: L(R.kanaele).map(x => ({ wert: String(x.schluessel ?? ''), text: String(x.name || '') })) });
    if (k === 'monat') felder.push({ typ: 'auswahl', name: 'monat', label: 'Monat', wert: String((EF && EF.monat) || (MON[0] || {}).schluessel || ''), optionen: MON.map(x => ({ wert: x.schluessel, text: String(x.name) })) });
    if (['vergleich', 'wunsch'].includes(k)) {
      const frei = zr.zeitraum === 'frei';
      felder.push({ typ: 'auswahl', name: 'zeitraum', label: 'Zeitraum', wert: String(zr.zeitraum || art.zeitraum || ''), optionen: L(R.zeitraeume).map(x => ({ wert: x.schluessel, text: String(x.name) })) },
        { typ: 'datum', name: 'von', label: 'Von (eigener Zeitraum)', wert: frei ? String(zr.von || '') : '' }, { typ: 'datum', name: 'bis', label: 'Bis (eigener Zeitraum)', wert: frei ? String(zr.bis || '') : '' });
    }
    if (k === 'wunsch') felder.push({ typ: 'mehrfach', name: 'bausteine', label: 'Bausteine', wert: gBau, breite: 'voll', optionen: L(R.bausteine).filter(x => x.wunsch === true).map(x => ({ wert: x.schluessel, text: String(x.name), neben: String(x.beschreibung || '') })) },
      { typ: 'text', name: 'titel', label: 'Titel', wert: String((VA ? VA.titel : EF ? EF.titel : '') || ''), platzhalter: 'Bericht nach Wunsch', breite: 'voll' });
    felder.push({ typ: 'auswahl', name: 'mit_agentur', label: 'Agentur im Report', wert: gAgentur ? 'ja' : 'nein', breite: 'voll', optionen: [{ wert: 'ja', text: 'Mit Agenturname und Logo' }, { wert: 'nein', text: 'Ohne Agenturname (neutral)' }] });
    const werte = Object.assign({ art: k }, V ? { vorlage_id: id9(V.id) } : {});
    const knoepfe = [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Report erstellen', name: 'modus', wert: 'erstellen' }];
    if (k !== 'kampagne') {
      const PL = L(R.plaene);
      felder.push({ typ: 'text', name: 'vorlage_name', label: 'Name der Vorlage (zum Speichern)', wert: V ? String(V.name || '') : '', breite: 'voll' },
        { typ: 'auswahl', name: 'plan', label: 'Wiederholung der Vorlage', wert: V ? String(V.plan || '') : String((PL[0] || {}).schluessel || ''), breite: 'voll', optionen: PL.map(x => ({ wert: x.schluessel, text: String(x.name) })) });
      knoepfe.splice(1, 0, { text: V ? 'Vorlage ändern' : 'Als Vorlage speichern', art: 'neben', name: 'modus', wert: 'vorlage_speichern' });
    }
    neuInhalt.push({ typ: 'formular', id: 'bericht', aktion: 'tr_bericht', werte, spalten: 2, felder, knoepfe });
    if (V) neuInhalt.push({ typ: 'aktion', text: 'Vorlage löschen', aktion: 'tr_vorlage_loeschen', werte: { vorlage_id: id9(V.id) }, frage: 'Vorlage löschen? Bereits erstellte Reports bleiben erhalten.' });
  }
}
const fenster = [{ id: 'neu', art: 'dialog', titel: V ? 'Vorlage „' + String(V.name || '') + '“' : art ? String(art.name) : 'Report erstellen', offen: !!(art || V), schliessen_ziel: hier({}), inhalt: neuInhalt }];
kopf.hauptaktion = { text: 'Report erstellen', fenster: 'neu' };
return [{ json: { inhalt: { seite: kopf, ueberblick: knapp(ueberblick), abschnitte, fenster } } }];

// Parameter (ALLY 27, Talent-Reports): Sitzung; Filter der Liste (art, talent), neuer Report (neu = Art), Vorlage bearbeiten (vorlage), Seiten der Listen (aus ?p= über ALLY 20).
const E = $input.first().json;
const P = E.parameter || {};
const S = E.seiten || {};
const ARTEN = ['monat', 'kampagne', 'vergleich', 'mediakit', 'wunsch'];
const nr = v => /^[0-9]{1,9}$/.test(String(v || '')) ? String(v) : '';
const f = {};
if (ARTEN.includes(String(P.art || ''))) f.art = String(P.art);
if (nr(P.talent)) f.talent = nr(P.talent);
if (ARTEN.includes(String(P.neu || ''))) f.neu = String(P.neu);
if (nr(P.vorlage)) f.vorlage = nr(P.vorlage);
if (Number(S.berichte) > 1) f.seite = String(Math.min(99999, Number(S.berichte)));
if (Number(S.vorlagen) > 1) f.vseite = String(Math.min(99999, Number(S.vorlagen)));
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', JSON.stringify(f)] } }];

// Downloads und Monatswahl (ALLY 27, Punkt 5h, Stefan 21.10.2026): ergänzt die Talent-Reports wie in ALLY 8, ohne „Seite beschreiben“ zu ändern.
// 1. Erstellte Reports: Spalte „Datei“ mit „PDF herunterladen“ (nur wenn die Datenbank den Report zum Herunterladen freigibt, Feld herunterladen) über die geprüfte
//    Seite „datei“ (tr = Report; ALLY 20 prüft Rechte und holt die Datei über SPEICHER 1, nie ein Direktlink); darunter der Ort im Speicherort wie bisher.
// 2. Vorlagen der Art Monatsreport: „Jetzt erstellen“ mit Monatswahl („wie gespeichert“ oder ein Monat, Feld monat wie ALLY 8) in einem kleinen Fenster.
const aus = $input.all().map(x => x.json);
const R = (($('Daten laden').first().json || {}).r) || {};
const s = v => String(v ?? '');
const L = x => Array.isArray(x) ? x : [];
const id9 = v => /^[0-9]{1,9}$/.test(s(v)) ? s(v) : '';
const id12 = v => /^[0-9]{1,12}$/.test(s(v)) ? s(v) : '';
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || !Array.isArray(I.abschnitte) || R.ok !== true) continue;
  // 1. Erstellte Reports
  const BZ = L((R.berichte || {}).zeilen);
  const ab = I.abschnitte.find(a => a && a.id === 'berichte');
  const tab = ab ? L(ab.inhalt).find(b => b && b.typ === 'tabelle' && b.id === 'berichte') : null;
  if (tab && L(tab.zeilen).length === BZ.length) {
    tab.spalten = L(tab.spalten).map(c => c.schluessel === 'ort' ? Object.assign({}, c, { titel: 'Datei' }) : c);
    tab.zeilen.forEach((z, i) => { const x = BZ[i] || {}, rid = id12(x.id), ort = x.pfad ? 'Im Speicherort: ' + s(x.pfad) + (x.ort ? ' (' + s(x.ort) + ')' : '') : '';
      if (!z || !z.zellen) return;
      z.zellen.ort = x.herunterladen && rid ? Object.assign({ text: 'PDF herunterladen', ziel: { seite: 'datei', parameter: { tr: rid } } }, ort ? { neben: ort } : {}) : (ort ? { text: '–', neben: ort } : '–'); });
  }
  // 2. Vorlagen: Monatsreport „Jetzt erstellen“ mit Monatswahl
  const MON = L(R.monate), VZ = L((R.vorlagen || {}).zeilen).filter(x => id9(x.id));
  const vab = I.abschnitte.find(a => a && a.id === 'vorlagen');
  const vtab = vab ? L(vab.inhalt).find(b => b && b.typ === 'tabelle' && b.id === 'vorlagen') : null;
  if (vtab && MON.length && L(vtab.zeilen).length === VZ.length) {
    I.fenster = L(I.fenster);
    vtab.zeilen.forEach((z, i) => { const x = VZ[i]; if (!z || !z.zellen || x.art !== 'monat') return;
      const fid = 'jetzt-' + id9(x.id);
      z.zellen.aktion = { aktion: { text: 'Jetzt erstellen', fenster: fid } };
      I.fenster.push({ id: fid, art: 'dialog', titel: 'Report aus „' + s(x.name) + '“ erstellen', inhalt: [{ typ: 'formular', id: fid, aktion: 'tr_vorlage_erstellen', werte: { vorlage_id: id9(x.id) },
        felder: [{ typ: 'auswahl', name: 'monat', label: 'Monat', wert: '', breite: 'voll', optionen: [{ wert: '', text: 'wie gespeichert' }].concat(MON.map(m => ({ wert: s(m.schluessel), text: s(m.name) }))) }],
        knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Jetzt erstellen' }] }] });
    });
  }
}
return aus.map(json => ({ json }));

// Vorlagen mit Papierkorb (ALLY 27, Migration 132, E13 „Löschen = Papierkorb“, Stefan 23.10.2026; Plan freigegeben vom Koordinator).
// Ergänzt „Seite beschreiben“ und „Downloads und Monatswahl“, ohne sie zu ändern (Muster wie „Absender-Regeln (Papierkorb)“, Migration 128):
//   „Vorlage löschen“ heißt „In den Papierkorb“ (Aktion tr_vorlage_loeschen legt die Vorlage jetzt in den Papierkorb); Knopf „Papierkorb“ im Kopf ohne Zähler (E9).
//   Unterseite papierkorb=1: die eigenen Vorlagen im Papierkorb mit „Wiederherstellen“ und „Endgültig löschen“, oben „Papierkorb leeren“ (genau die angezeigten, höchstens 1000); 10 je Seite (E8).
//   Die Unterseite zeigt nur den Papierkorb (ohne Kennzahlen, Offen und Meldungen der Reports).
// Die Daten liefert die Datenbank (talents_berichte_web.vorlagen_papierkorb, nur eigene Vorlagen); die Aktionen prüfen die Rechte selbst (talents_vorlage_papierkorb).
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const P = E.parameter || {};
const R = D.r && typeof D.r === 'object' ? D.r : {};
const LI = x => Array.isArray(x) ? x : [];
const s0 = v => String(v ?? '');
const JE = 10;
const MAX = 1000;
const LEER = 'Das lässt sich nicht rückgängig machen.';
const blatt = (tab, n) => { const s = Math.max(1, Number((E.seiten || {})[tab]) || 1); return Math.min(s, Math.max(1, Math.ceil(n / JE))); };
const bloecke = I => {
  const aus = [];
  const geh = arr => { for (const b of LI(arr)) { if (!b || typeof b !== 'object') continue; aus.push(b); if (Array.isArray(b.inhalt)) geh(b.inhalt); } };
  for (const a of LI(I.abschnitte)) geh(a && a.inhalt);
  for (const f of LI(I.fenster)) geh(f && f.inhalt);
  geh(I.bloecke);
  return aus;
};

return $input.all().map(it => {
  const j = it.json || {};
  const I = j.inhalt;
  const PK = Array.isArray(R.vorlagen_papierkorb) ? R.vorlagen_papierkorb : null;
  if (!I || typeof I !== 'object' || !I.seite || D.ok !== true || R.ok !== true || !PK) return it;
  const seite = I.seite;
